function flattenRuleRanges(e){const n=[],t=e.media||[];for(let e=0;e<t.length;++e){const r=t[e];r.range&&n.push({range:r.range,name:"media #"+e})}for(let t=0;t<e.selectors.length;++t){const r=e.selectors[t];r.range&&n.push({range:r.range,name:"selector #"+t})}e.style.range&&n.push({range:e.style.range,name:"style range"});const r=e.style.allProperties();for(let e=0;e<r.length;++e){const t=r[e];t.range&&n.push({range:t.range,name:"property >>"+t.text+"<<"})}return n}function compareRuleRanges(e,n){if(e.selectorText!==n.selectorText)return TestRunner.addResult("Error: rule selectors are not equal: "+e.selectorText+" != "+n.selectorText),!1;const t=flattenRuleRanges(e),r=flattenRuleRanges(n);if(t.length!==r.length)return TestRunner.addResult("Error: rule range amount is not equal: "+t.length+" != "+r.length),!1;for(let e=0;e<t.length;++e){const n=t[e],s=r[e];if(n.name!==s.name)return TestRunner.addResult("Error: rule names are not equal: "+n.name+" != "+s.name),!1;if(!n.range.equal(s.range))return TestRunner.addResult("Error: ranges '"+n.name+"' are not equal: "+n.range.toString()+" != "+s.range.toString()),!1}return TestRunner.addResult(t.length+" rule ranges are equal."),!0}self.ElementsTestRunner=self.ElementsTestRunner||{},ElementsTestRunner.validateRuleRanges=function(e,n,t){function r(){const e=ElementsTestRunner.getMatchedRules();if(e.length!==n.length)return TestRunner.addResult(String.sprintf("Error: rules sizes are not equal! Expected: %d, actual: %d",e.length,n.length)),void TestRunner.completeTest();for(let t=0;t<e.length;++t)if(!compareRuleRanges(n[t],e[t]))return void TestRunner.completeTest();t()}ElementsTestRunner.selectNodeAndWaitForStyles("other",(function(){ElementsTestRunner.selectNodeAndWaitForStyles(e,r)}))},ElementsTestRunner.getMatchedRules=function(){const e=[];for(const n of UI.panels.elements.stylesWidget.sectionBlocks)for(const t of n.sections){const n=t.style().parentRule;n&&e.push(n)}return e};